const usersForNotifying = `-- name: UsersForNotifying :many
SELECT u.id, u.email, u.email_verified, u.display_name, u.timezone, coalesce(np.prefs, '{}')::jsonb AS prefs
FROM users u LEFT JOIN notification_prefs np ON np.user_id = u.id
WHERE u.id = ANY($1::uuid[])
`

type UsersForNotifyingRow struct {
	ID            pgtype.UUID `json:"id"`
	Email         string      `json:"email"`
	EmailVerified bool        `json:"email_verified"`
	DisplayName   string      `json:"display_name"`
	Timezone      string      `json:"timezone"`
	Prefs         []byte      `json:"prefs"`
}

func (q *Queries) UsersForNotifying(ctx context.Context, ids []pgtype.UUID) ([]UsersForNotifyingRow, error) {
	rows, err := q.db.Query(ctx, usersForNotifying, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UsersForNotifyingRow
	for rows.Next() {
		var i UsersForNotifyingRow
		if err := rows.Scan(
			&i.ID,
			&i.Email,
			&i.EmailVerified,
			&i.DisplayName,
			&i.Timezone,
			&i.Prefs,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
